function incTable(list){return `<div class="itsm-tw"><table class="itsm-t"><thead><tr><th>Number</th><th>Priority</th><th>Short description</th><th>Service</th><th>State</th><th>Group</th><th>Assigned to</th><th>Response</th><th>Resolution</th><th>Age</th></tr></thead><tbody>${list.map(i=>{const s=slaOf(i);return `<tr class="itsm-row" data-itsm-inc="${i.id}" tabindex="0"><td><b>${i.id}</b>${i.maj?' <span class="pill bad">Major</span>':""}</td><td>${pPill(prio(i))}</td><td class="itsm-tt">${esc(i.t)}</td><td>${esc(i.svc)}</td><td>${statePill(i.st)}</td><td>${esc(i.grp)}</td><td>${who(i.own)}</td><td>${slaChip("Resp",s.resp)}</td><td>${slaChip("Reso",s.res)}</td><td class="num">${fH(i.age)}</td></tr>`}).join("")||`<tr><td colspan="10">${empty("No incidents match","Clear a filter to see more.")}</td></tr>`}</tbody></table></div>`}
const kcard=i=>{const s=slaOf(i);return `<div class="itsm-kc" data-dnd-id="${i.id}" tabindex="0" data-itsm-inc="${i.id}">${grip}<div class="row sp"><b>${i.id}</b><span class="row" style="gap:6px">${i.maj?'<span class="pill bad">Major</span>':""}${pPill(prio(i))}</span></div><div class="itsm-kt">${esc(i.t)}</div><div class="row small" style="gap:6px"><span class="pill mute">${esc(i.svc)}</span>${slaChip(s.paused?"Paused":"SLA",s.res)}</div><div class="row sp small">${who(i.own)}<span class="muted">${fH(i.age)} old</span></div></div>`};
function boardHTML(){const cols=STS.map(s=>{const l=X.inc.filter(i=>i.st===s).sort((a,b)=>prio(a)-prio(b)||b.age-a.age);return `<div class="itsm-col"><div class="itsm-colh"><b>${s}</b><span class="pill ${STC[s]}">${l.length}</span></div><div class="itsm-lane" data-dnd="st:${s}" data-dnd-scope="itsm_inc">${l.map(kcard).join("")}</div></div>`}).join("");
 const as=ASSIGNEES.map(n=>`<div class="itsm-as" data-dnd="own:${esc(n)}" data-dnd-scope="itsm_inc">${avatar(n)}<span><b>${esc(n)}</b><small class="muted">${X.inc.filter(i=>isOpen(i)&&i.own===n).length} open</small></span></div>`).join("");
 return `<div class="muted small" data-role="story">Drag a card to another column to change its state. Resolving or holding asks for the required details. Drag a card onto a person below to assign it. Keyboard: focus a card, then Alt plus arrow keys.</div><div class="eyebrow">Drop a card on a person to assign it</div><div class="itsm-assign">${as}</div><div class="itsm-board">${cols}</div>`}
function matrixHTML(){const m=X.mx||(X.mx={imp:1,urg:2}),open=X.inc.filter(isOpen),p=mxcell(m.imp,m.urg),id=pid();
 const cells=[1,2,3].map(u=>`<div class="itsm-mxh">${IMPL[u]} urgency</div>`+[1,2,3].map(im=>{const pr=Math.min(4,im+u-1),inc=open.filter(i=>i.imp===im&&i.urg===u);return `<button class="itsm-mxc p${pr}" data-itsm-mx="${im}:${u}" aria-pressed="${m.imp===im&&m.urg===u}" title="Impact ${IMPL[im]} (${im}) + Urgency ${IMPL[u]} (${u}) − 1 = ${im+u-1} → P${pr}"><b>P${pr}</b><span>${inc.length} open</span><span class="itsm-mxi">${inc.slice(0,3).map(i=>i.id.slice(3)).join(" ")}</span></button>`}).join("")).join("");
 return `<div class="grid g2" style="align-items:start"><div class="itsm-mxw"><div class="itsm-mx"><div></div>${[1,2,3].map(im=>`<div class="itsm-mxh">${IMPL[im]} impact</div>`).join("")}${cells}</div></div><div class="grid" style="gap:14px"><div class="formula" data-role="metric">Priority = Impact + Urgency − 1, capped at 4 (High = 1, Medium = 2, Low = 3)</div><p class="muted small">Impact is how many people or how critical a service is. Urgency is how fast it must be fixed. Select any cell to try it.</p><div class="mini glass" style="grid-template-columns:repeat(3,1fr)"><div><span class="num" data-role="metric">P${Math.min(4,m.imp+m.urg-1)}</span><small>${esc(p.n)}</small></div><div><span class="num" data-role="metric">${fH(p.resp)}</span><small>Response target</small></div><div><span class="num" data-role="metric">${fH(p.res)}</span><small>Resolution target</small></div></div><div class="itsm-tw"><table class="itsm-t sm"><thead><tr><th>Priority</th><th>Meaning</th><th>Response</th><th>Resolution</th></tr></thead><tbody>${[1,2,3,4].map(n=>`<tr><td>${pPill(n)}</td><td>${PRI[n].n}</td><td class="num">${fH(PRI[n].resp)}</td><td class="num">${fH(PRI[n].res)}</td></tr>`).join("")}</tbody></table></div><div class="row"><button class="chip" popovertarget="${id}">Why these targets?</button></div><div popover id="${id}" class="pop glass"><div class="eyebrow">Policy</div><h3>How targets are set</h3><p class="muted">Targets follow ITIL 4 practice: critical work is acknowledged in minutes, low priority within the business day. Clocks pause while an incident waits on a caller, vendor or change. Targets are in elapsed work hours in this prototype.</p><button class="btn" popovertarget="${id}" popovertargetaction="hide">Close</button></div></div></div>`}
function slaTab(){const open=X.inc.filter(isOpen).map(i=>({i,s:slaOf(i)})).sort((a,b)=>Math.min(a.s.res.f,a.s.resp.done?9:a.s.resp.f)-Math.min(b.s.res.f,b.s.resp.done?9:b.s.resp.f));const br=open.filter(x=>x.s.breach).length,rk=open.filter(x=>x.s.risk&&!x.s.breach).length;
 return `${tiles([TL("Breached",br,"Past target, act now",br?"bad":"good"),TL("At risk",rk,"Under 25% of target left",rk?"warn":"good"),TL("On track",open.length-br-rk,"Plenty of time","good"),`<div class="tile glass"><span class="lbl">SLA compliance (30 days)</span><span class="big num" data-role="metric">${METRICS.m_itsm_sla.cur}%</span><span class="row">${fchip("m_itsm_sla")}</span></div>`])}<div class="itsm-tw"><table class="itsm-t"><thead><tr><th>Incident</th><th>Priority</th><th>Response timer</th><th>Resolution timer</th><th>Owner</th></tr></thead><tbody>${open.map(({i,s})=>`<tr class="itsm-row" data-itsm-inc="${i.id}" tabindex="0"><td><b>${i.id}</b><br><span class="muted small">${esc(i.t.slice(0,48))}</span></td><td>${pPill(prio(i))}</td><td>${slaMeter("Response",s.resp)}</td><td>${slaMeter("Resolution",s.res,s.paused)}</td><td>${who(i.own)}</td></tr>`).join("")}</tbody></table></div>`}
