 const flt=`<div class="itsm-filters">${sel("st","State",[["open","All open"],["New","New"],["In progress","In progress"],["On hold","On hold"],["Resolved","Resolved"],["all","All"]])}${sel("pr","Priority",[["","Any"],["1","P1"],["2","P2"],["3","P3"],["4","P4"]])}${sel("grp","Assignment group",[["","Any"]].concat(GRPS))}${sel("svc","Service",[["","Any"]].concat(SVC))}<label class="itsm-f itsm-fq"><span>Search</span><input class="fin" id="itsmQ" data-itsm-q placeholder="Number, text, caller" value="${esc(X.f.q)}"></label></div>`;
 const queue=`${flt}<div class="muted small" data-role="story">${list.length} of ${X.inc.length} incidents shown, highest priority first. Select a row for the timeline, SLA timers and AI triage.</div>${incTable(list)}`;
