function tplTab(){return `<div class="muted small" data-role="story">${X.tpl.filter(t=>t.st==="Approved").length} approved templates cover the routine changes. Using one needs no CAB vote, only a calendar slot.</div><div class="row"><button class="btn primary" data-itsm-tnew>New template</button></div><div class="grid g3">${X.tpl.map(t=>`<div class="itsm-pc glass"><div class="row sp"><b>${t.id}</b><span class="pill ${t.st==="Approved"?"good":"warn"}">${t.st}</span></div><div class="itsm-kt">${esc(t.n)}</div><p class="small muted">${esc(t.pre)}</p><div class="row small" style="gap:6px"><span class="pill mute">${esc(t.svc)}</span><span class="pill metric">${t.ok}% success · ${t.runs} runs</span><span class="pill mute">${esc(t.freq)} · ${esc(t.dur)}</span></div><div class="row"><button class="btn primary" data-itsm-tuse="${t.id}">Use template</button></div></div>`).join("")}</div>${card("Templates Claude suggests",`Three Normal changes keep repeating without trouble`,`<div class="itsm-list">${[["Scale Azure SQL up and down for a load test","3 Normal changes in 90 days, all successful, median risk 14","Azure platform"],["Deploy a minor search index schema update","4 Normal changes in 90 days, all successful, median risk 11","Search service"]].map((s,n)=>`<div class="itsm-li static"><span>${aiChip({model:"Change Risk Advisor",conf:.8-n*.04,title:"Why a template?",note:"Repeated Normal changes with low risk and no failures are candidates for pre-approval.",src:["Closed changes","Risk scores"],guards:["Suggestion only; the CAB approves templates"]})}</span><span><b>${s[0]}</b><br><small class="muted">${s[1]}</small></span><button class="btn" data-itsm-tsug="${n}">Draft template</button></div>`).join("")}</div>`)}`}
