 const wks=["2026-09-07","2026-09-14","2026-09-21","2026-09-28","2026-10-05"].map(w=>{const l=done_.filter(c=>c.start>=w&&c.start<addD(w,7));return {w,ok:l.filter(c=>c.out!=="Failed").length,f:l.filter(c=>c.out==="Failed").length}}),mx=Math.max(...wks.map(w=>w.ok+w.f));
