function pirTab(){const m=X.mi,p=m.pir;return `<div class="grid g2" style="align-items:start">${card("Blameless review template","Same structure every time so lessons compare across incidents",`<ol class="itsm-tpl"><li><b>Summary and impact</b> People affected, duration, customer-facing or not.</li><li><b>Timeline</b> Built automatically from the war room.</li><li><b>Five whys</b> Follow the cause to a process or capacity gap, never to a person.</li><li><b>What went well, what to improve</b></li><li><b>Action items</b> Each needs an owner and a date, and becomes a task.</li></ol><div class="row"><button class="btn primary" data-itsm-pir>${p?"Edit review":"Start the review"}</button>${m.restored==null?'<span class="muted small">Due within 5 business days of restore.</span>':'<span class="pill warn">Due Oct 13</span>'}</div>${p?`<p class="small" data-role="story"><b>Saved ${p.saved}.</b> ${esc(p.sum)}</p>`:""}`,aiChip({model:"Claude Sonnet",conf:.78,title:"AI drafted review",note:"Fills the summary and whys from the timeline and the problem record PRB0010. A person edits and approves.",src:["War room timeline","PRB0010","Changes"],guards:["Draft only","Blameless wording check"]}))}${card("Action items","Reviews end in work, not a document",`<div class="itsm-list">${X.tasks.map(t=>`<button class="itsm-li" data-itsm-task="${t.id}"><i class="itsm-tk ${t.done?"on":""}"></i><span class="${t.done?"done":""}"><b>${esc(t.t)}</b><br><small class="muted">${esc(t.who)} · due ${fd(t.due)} · ${esc(t.from)}</small></span></button>`).join("")||empty("No tasks yet")}</div><p class="small muted">${X.tasks.filter(t=>!t.done).length} open. These are tracked here and appear in each owner's work list.</p>`)}${card("Time to restore","Major incident measure, includes this one",`<div class="row"><span class="num" style="font-size:42px" data-role="metric">${METRICS.m_itsm_mttr.cur}h</span>${fchip("m_itsm_mttr")}</div><p class="small muted" data-role="story">Average of 3 earlier major incidents (1.9, 2.4 and 3.6 hours) and this one at ${fH(miEl())}${m.restored==null?" so far":""}.</p>`)}</div>`}
