function homeHTML(){syncM();const open=X.inc.filter(isOpen),p12=open.filter(i=>prio(i)<=2),risk_=open.filter(i=>slaOf(i).risk),br=open.filter(i=>slaOf(i).breach),n7=nextDays(7),co=allCollisions().filter(x=>x.kind==="hard"),fc=freezeConflicts(),m=X.mi,nf=FREEZE.filter(f=>f.from>TODAYI).sort((a,b)=>a.from.localeCompare(b.from))[0],inc=INC(m.inc);
 const bySv={};X.inc.forEach(i=>{bySv[i.svc]=(bySv[i.svc]||0)+1});const sv=Object.entries(bySv).sort((a,b)=>b[1]-a[1]).slice(0,5),mxs=sv[0][1];
 const el=open.map(i=>i.age-(i.pausedH||0)),bk=[["Under 4 hours",el.filter(h=>h<4).length],["4 to 24 hours",el.filter(h=>h>=4&&h<24).length],["1 to 3 days",el.filter(h=>h>=24&&h<72).length],["Over 3 days",el.filter(h=>h>=72).length]],mxb=Math.max(1,...bk.map(b=>b[1]));
 const worst=[...open].sort((a,b)=>{const f=i=>{const s=slaOf(i);return Math.min(s.res.f,s.resp.done?9:s.resp.f)};return f(a)-f(b)}).slice(0,5);
 const hero_=hero("Service management · Meridian Standards Foundation","Service desk overview",`<b>${p12.length} open P1 or P2</b> incidents, led by the Codification Portal slowdown that has run <b>${fH(miEl())}</b>. <b>${risk_.length}</b> SLA timers are at risk and <b>${br.length}</b> already breached. The change calendar has <b>${n7.length}</b> changes in the next 7 days${co.length?`, with <b>${co.length}</b> collision${co.length>1?"s":""} to resolve`:""}; ${nf?`the next freeze, <b>${esc(nf.n)}</b>, starts ${fd(nf.from)} (${dif(nf.from,TODAYI)} days away) and <b>${fc.length}</b> planned change${fc.length===1?"":"s"} would land inside it`:""}.`,`<div class="row"><button class="btn primary" data-itsm-new>Log incident</button><button class="btn" data-itsm-cnew>Request change</button><button class="btn danger" data-itsm-midecl>${m.on?"Open the war room":"Start major incident"}</button>${fchip("m_itsm_sla")}${fchip("m_itsm_cfr")}${fchip("m_itsm_backlog")}${fchip("m_itsm_mttr")}${aiChip({model:"Claude Sonnet",conf:.86,title:"How this summary is written",note:"Reads the incident queue, change calendar and war room, and states what needs a decision first.",src:["Incidents","Change calendar","Major incident"],guards:["Read-only summary","Every number is a metric or story"]})}</div>`);
 const tl=[TL("Open P1 or P2",p12.length,"of "+open.length+" open incidents",p12.length>2?"bad":"warn"),TL("SLA at risk",risk_.length,br.length+" breached",br.length?"bad":"warn"),`<div class="tile glass"><span class="lbl">Backlog age</span><span class="big num" data-role="metric">${METRICS.m_itsm_backlog.cur}h</span><span class="row small">average open time ${fchip("m_itsm_backlog","Formula")}</span></div>`,TL("Changes, next 7 days",n7.length,co.length+" collision"+(co.length===1?"":"s"),co.length?"warn":"good")];
 return `<div class="screen">${hero_}${lensNote()}${tiles(tl)}
 <div class="grid g2" style="align-items:start">${m.on?card(m.restored!=null?"Major incident restored":"Major incident in progress",inc?esc(inc.t):"",`<div class="itsm-clock"><div><span class="num" data-role="metric">${fH(miEl())}</span><small class="muted">${m.restored!=null?"time to restore":"elapsed"}</small></div><div class="row">${m.restored!=null?'<span class="pill good">Restored</span>':'<span class="live"><i></i><b>Live</b></span>'}${unfilled().length?`<span class="pill warn">${unfilled().length} roles empty</span>`:""}</div></div><p class="small" data-role="story">${esc([...m.tl].sort((a,b)=>a[0]-b[0])[0][3])}</p><div class="row"><button class="btn primary" data-go="itsm_mi">Open the war room</button><button class="btn" data-itsm-inc="${m.inc}">Incident</button></div>`):card("No major incident","The last one was restored and reviewed",`<button class="btn danger" data-itsm-midecl>Start major incident</button>`)}
 ${card("SLA at risk","Closest to breaching first",`<div class="itsm-list">${worst.map(i=>{const s=slaOf(i),t=!s.resp.done&&s.resp.f<s.res.f?["Response",s.resp]:["Resolution",s.res];return `<button class="itsm-li" data-itsm-inc="${i.id}"><b>${i.id}</b><span>${esc(i.t.slice(0,52))}</span>${pPill(prio(i))}${slaChip(t[0].slice(0,4)+".",t[1])}</button>`}).join("")}</div><div class="row"><button class="btn" data-go="itsm_inc">Open the queue</button></div>`)}
 ${card("Change calendar: next 7 days",`${n7.length} scheduled. ${nf?"Next freeze "+fd(nf.from)+" to "+fd(nf.to)+".":""}`,`<div class="itsm-list">${n7.map(c=>`<button class="itsm-li" data-itsm-chg="${c.id}"><b>${wk(c.start)} ${fd(c.start)}</b><span>${esc(c.t.slice(0,50))}</span>${typePill(c.type)}</button>`).join("")||empty("Nothing scheduled")}</div>${co.map(x=>`<div class="itsm-warn bad"><b>${x.a.id}</b> and <b>${x.b.id}</b> collide on ${esc(x.sh.join(", "))}.</div>`).join("")}<div class="row"><button class="btn" data-go="itsm_chg">Open the calendar</button><button class="btn quiet" data-ask="Is there a change freeze?">Is there a freeze?</button></div>`)}
 ${card("Top services by incidents","Incidents in the last 30 days, all priorities",`<div class="itsm-hb">${sv.map(([s,n])=>`<div class="itsm-hr"><span>${esc(s)}</span><u><i style="width:${n/mxs*100}%"></i></u><b class="num" data-role="metric">${n}</b></div>`).join("")}</div><p class="small muted" data-role="story">${esc(sv[0][0])} leads with ${sv[0][1]} incidents. Most trace to PRB0010 (hosting capacity) and PRB0007 (the Lumen indexer).</p>`)}
 ${card("Backlog age","How long open incidents have been waiting",`<div class="itsm-hb">${bk.map(([l,n])=>`<div class="itsm-hr"><span>${l}</span><u><i class="${l.startsWith("Over")?"bad":l.startsWith("1")?"warn":""}" style="width:${n/mxb*100}%"></i></u><b class="num" data-role="metric">${n}</b></div>`).join("")}</div>`,fchip("m_itsm_backlog"))}
 ${card("Go to","Everything in service management",`<div class="itsm-go">${[["itsm_inc","Incidents","Queue, board, priority matrix, SLA timers"],["itsm_prb","Problems and known errors","Root cause, KEDB, repeat incidents"],["itsm_chg","Changes","Calendar, CAB, risk, templates"],["itsm_rel","Releases","Trains, stages, go or no-go"],["itsm_mi","Major incident","War room, comms, status page, review"]].map(g=>`<button class="itsm-gi glass" data-go="${g[0]}"><b>${g[1]}</b><small class="muted">${g[2]}</small></button>`).join("")}</div>`)}</div></div>`}
