/* ---------- drag and drop ---------- */
DND.on("itsm_inc",(id,from,to)=>{const i=INC(id);if(!i)return;
 if(to.startsWith("own:")){const n=to.slice(4);i.own=n;if(i.st==="New")i.st="In progress";if(i.respH==null)i.respH=i.age;i.notes.push({a:0,w:"System",k:"System",x:"Assigned to "+n+" by drag and drop."});return done("Incident assigned",id+" → "+n)}
 const s=to.slice(3);if(s===i.st){render();return}if(s==="Resolved"){render();return resolveForm(id)}if(s==="On hold"){render();return holdForm(id)}setState(i,s)});
DND.on("itsm_link",(id,from,to)=>{const i=INC(id);if(!i)return;const t=to==="pool"?"":to.slice(4);if(t===(i.prb||"")){render();return}i.prb=t;i.notes.push({a:0,w:"System",k:"System",x:t?"Linked to problem "+t+" by drag and drop.":"Unlinked from its problem."});
 done(t?"Incident linked to problem":"Incident unlinked",id+(t?" → "+t+" ("+incsOf(PRB(t)).length+" incidents now)":""))});
DND.on("itsm_cal",(id,from,to)=>{const c=CHGB(id);if(!c)return;const day=to.slice(4);if(day===c.start){render();return}
 if(day<TODAYI){toast("A change cannot move into the past","warn");render();return}
 const len=dif(c.end,c.start),old=c.start;c.start=day;c.end=addD(day,len);const cl=collisions(c).filter(x=>x.kind==="hard"),fz=freezeHits(c);
 syncM();audit("rescheduled change",id+" "+fd(old)+" → "+fd(day)+(cl.length?" · collides with "+cl.map(x=>x.o.id).join(", "):"")+(fz.length?" · inside "+fz[0].n:""));
 toast(id+" moved to "+wk(day)+" "+fd(day)+". "+(cl.length?"Collision with "+cl.map(x=>x.o.id).join(", ")+" on "+cl[0].sh.join(", ")+".":fz.length?"Inside "+fz[0].n+": needs an exception.":!wkday(day)?"Weekend: check on-call cover.":"No collisions, no freeze."),cl.length||fz.length?"bad":"good");render()});
DND.on("itsm_rel",(id,from,to)=>{const r=REL(id),s=to.slice(4);if(!r||s===r.stage){render();return}const g=lastGng(r);
 if(s==="Deploy"&&!(g&&g.dec!=="No-go")){toast(id+" needs a recorded go or conditional go before Deploy","warn");render();return gngForm(id)}
 if(s==="Review"&&r.stage!=="Deploy"){toast("A release reaches Review only after Deploy","warn");render();return}
 r.stage=s;done("Release moved",id+" → "+s)});
DND.on("itsm_relchg",(id,from,to)=>{const c=CHGB(id);if(!c)return;const t=to.slice(4);c.rel=t==="none"?"":t;done("Change moved",id+" → "+(c.rel||"unassigned")+(c.rel?" ("+readiness(REL(c.rel))+"% ready)":""))});
DND.on("itsm_role",(id,from,to)=>{const m=X.mi;if(from===to){render();return}const fr=from.startsWith("role:")?from.slice(5):null;Object.keys(m.roles).forEach(k=>{if(m.roles[k]===id)m.roles[k]=""});
 if(to==="pool"){m.tl.push([0,"System","Update",id+" released from "+(MROLES.find(r=>r[0]===fr)||[0,"a role"])[1]+"."]);return done("Role released",id)}
 const r=to.slice(5),prev=m.roles[r];m.roles[r]=id;if(fr&&prev)m.roles[fr]=prev;const rn=MROLES.find(x=>x[0]===r)[1];m.tl.push([0,"System","Update",id+" is now "+rn.toLowerCase()+"."+(prev&&prev!==id?" "+prev+" moved aside.":"")]);done("Role assigned",id+" → "+rn)});

