 if(d.itsmAct)return incAct(d.itsmAct,d.id);
 if(d.itsmNote){const ta=$("#itsmNoteTxt"),x=ta&&ta.value.trim();if(!x){ta&&ta.focus();toast("Write the note first","warn");return}const i=INC(d.id);i.notes.push({a:0,w:i.own||"Tom Becker",k:d.itsmNote,x});if(d.itsmNote==="Comment"&&i.respH==null)i.respH=i.age;audit("added "+d.itsmNote.toLowerCase(),d.id);toast(d.itsmNote+" added");render();return incDrawer(d.id)}
 if(d.itsmInc){closeDrawer();return incDrawer(d.itsmInc)}
 if(d.itsmMx){const [a,b]=d.itsmMx.split(":");X.mx={imp:+a,urg:+b};S.v.itsm_inc=2;render();return}
 if(d.itsmPrb){return prbDrawer(d.itsmPrb)}
